SELECT c.product_id,COALESCE(t.price,10) AS price FROM (SELECT DISTINCT product_id FROM Products ) AS c LEFT JOIN (SELECT product_id,new_price as price FROM Products 
WHERE (product_id,change_date) IN (SELECT product_id,MAX(change_date) as change_date FROM Products WHERE change_date<='2019-08-16' GROUP BY product_id)) as t ON c.product_id=t.product_id;